class Solution:
    def findGCD(self, nums: List[int]) -> int:
        i_min = min(nums)
        i_max = max(nums)
        greater = i_max
        while True:
            if greater % i_min == 0 and greater % i_max == 0:
                lcm = greater
                break
            greater += 1
        return int(i_min/(lcm/i_max))

class Solution:
    def maxRepeating(self, sequence: str, word: str) -> int:
        if word not in sequence:
            return 0

        left = 1
        right = len(sequence) // len(word)
        while left <= right:
            mid = (left + right) // 2
            if word * mid in sequence:
                left = mid + 1
            else:
                right = mid - 1

        return left - 1

class Solution:
    def maxSubarraySumCircular(self, A):
        total, max_sum, cur_max, min_sum, cur_min = 0, -float("inf"), 0, float("inf"), 0
        for a in A:
            cur_max = max(cur_max+a, a)
            max_sum = max(max_sum, cur_max)
            cur_min = min(cur_min+a, a)
            min_sum = min(min_sum, cur_min)
            total += a
        return max(max_sum, total-min_sum) if max_sum >= 0 else max_sum

